import {War} from './war.js';
import {analyse} from './market.js';
const $=id=>document.getElementById(id), C={green:'#39e89a',red:'#ff505d'};
let samples=[],lastPrice=0,lastTick=0,source='Coinbase',socket,retry=0,retryTimer,provider=0,stopped=false;
let stats={change:0,intensity:0,pressure:50,span:0},front=.5,live=false;
const reducedQuery=matchMedia('(prefers-reduced-motion: reduce)');let reduced=reducedQuery.matches;
let audio=null,sound=false;
function receive(price){if(!Number.isFinite(price)||price<=0)return;let now=Date.now();lastPrice=price;lastTick=now;retry=0;const sec=Math.floor(now/1000)*1000;if(samples.at(-1)?.t===sec)samples.at(-1).p=price;else samples.push({t:sec,p:price});samples=samples.filter(x=>now-x.t<=300000);$('price').textContent=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(price);}
function connect(){clearTimeout(retryTimer);if(stopped)return;const s=socket=new WebSocket(provider===0?'wss://ws-feed.exchange.coinbase.com':'wss://ws.kraken.com/v2');source=provider===0?'Coinbase':'Kraken';$('source').textContent=provider===0?'Coinbase Exchange · ETH/USD':'Kraken · ETH/USD';
 s.onopen=()=>{if(s!==socket)return;s.send(JSON.stringify(provider===0?{type:'subscribe',product_ids:['ETH-USD'],channels:['ticker','heartbeat']}:{method:'subscribe',params:{channel:'ticker',symbol:['ETH/USD'],snapshot:true}}));};
 s.onmessage=e=>{if(s!==socket)return;try{const d=JSON.parse(e.data);if(provider===0&&d.type==='ticker'&&d.product_id==='ETH-USD')receive(Number(d.price));if(provider===1&&d.channel==='ticker'&&d.data?.[0]?.symbol==='ETH/USD')receive(Number(d.data[0].last));}catch{}};
 s.onerror=()=>s.close();s.onclose=()=>{if(s!==socket||stopped)return;retry++;if(retry>=2){provider=1-provider;retry=0;samples=[];lastTick=0;lastPrice=0;$('price').textContent='—';}retryTimer=setTimeout(connect,Math.min(15000,1500*2**retry));};
 const deadline=setTimeout(()=>{if(s===socket&&Date.now()-lastTick>15000)s.close();},16000);s.addEventListener('close',()=>clearTimeout(deadline),{once:true});}
function update(){let age=Date.now()-lastTick;live=lastTick>0&&age<15000;stats=live?analyse(samples):{...stats,intensity:0,pressure:50};$('lamp').className=live?'live':'';$('connection').textContent=live?`${source} · EN DIRECT`:lastPrice?'FLUX INTERROMPU · reconnexion':'Connexion au marché…';$('notice').textContent=live?'':lastPrice?'Flux interrompu. Dernier prix reçu conservé.':'Connexion au flux ETH/USD…';if(!live&&socket?.readyState===WebSocket.OPEN&&age>20000)socket.close();
 const ready=live&&stats.span>=5, change=stats.change;
 $('change').textContent=ready?`${change>=0?'+':''}${change.toFixed(3)} % · ${stats.span>=59?'1 MIN':Math.max(1,Math.floor(stats.span))+' S'}`:live?'Observation du marché…':'En attente du flux';$('change').style.color=ready?(change>=0?C.green:C.red):'#a1aab7';
 let stage=!ready?'OBSERVATION DU MARCHÉ':stats.intensity>.8?'GUERRE TOTALE':Math.abs(change)<.012?'ESCARMOUCHE':change>0?'OFFENSIVE BULL':'OFFENSIVE BEAR';$('phase').textContent=live?stage:'EN ATTENTE DU MARCHÉ';$('phase').style.color=!ready?'#cbbaff':Math.abs(change)<.012?'#cbbaff':change>0?C.green:C.red;
 $('balance').style.width=stats.pressure+'%';$('bullShare').textContent=ready?Math.round(stats.pressure)+' %':'—';$('bearShare').textContent=ready?Math.round(100-stats.pressure)+' %':'—';$('window').textContent=ready?`fenêtre ${Math.min(60,Math.floor(stats.span))} s`:'observation';let level=ready?Math.max(1,Math.ceil(stats.intensity*5)):0;[...$('levels').children].forEach((e,i)=>e.classList.toggle('on',i<level));$('volLabel').textContent=['EN ATTENTE','CALME','MODÉRÉE','ÉLEVÉE','TRÈS ÉLEVÉE','EXTRÊME'][level];drawChart();}
function drawChart(){const c=$('chart'),r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);c.width=r.width*d;c.height=r.height*d;const g=c.getContext('2d');g.scale(d,d);let pts=samples;if(pts.length<2)return;let min=Math.min(...pts.map(x=>x.p)),max=Math.max(...pts.map(x=>x.p));let range=max-min||max*.0001;g.strokeStyle=stats.change>=0?C.green:C.red;g.lineWidth=1.5;g.beginPath();const x=i=>i/(pts.length-1)*r.width,y=p=>r.height-5-(p-min)/range*(r.height-10);pts.forEach((p,i)=>i?g.lineTo(x(i),y(p.p)):g.moveTo(0,y(p.p)));g.stroke();g.lineTo(r.width,r.height);g.lineTo(0,r.height);g.closePath();let fill=g.createLinearGradient(0,0,0,r.height);fill.addColorStop(0,stats.change>=0?'#39e89a30':'#ff505d30');fill.addColorStop(1,'transparent');g.fillStyle=fill;g.fill();}
$('sound').onclick=()=>{sound=!sound;if(sound){audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();}$('sound').textContent=sound?'Son on':'Son off';$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'Couper le son':'Activer le son');};
function rumble(power){if(!sound||!audio||audio.state!=='running')return;let length=audio.sampleRate*.22,buffer=audio.createBuffer(1,length,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*(1-i/length);let s=audio.createBufferSource(),f=audio.createBiquadFilter(),gain=audio.createGain();s.buffer=buffer;f.type='lowpass';f.frequency.value=200+power*300;gain.gain.value=.07*power;s.connect(f);f.connect(gain);gain.connect(audio.destination);s.start();s.onended=()=>{s.disconnect();f.disconnect();gain.disconnect();};}
function motionButton(){$('motion').textContent=reduced?'Mouvements réduits':'Mouvements';$('motion').setAttribute('aria-pressed',String(reduced));$('motion').setAttribute('aria-label',reduced?'Activer les animations complètes':'Réduire les animations');}
$('motion').onclick=()=>{reduced=!reduced;motionButton();};reducedQuery.addEventListener('change',e=>{reduced=e.matches;motionButton();});motionButton();
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('fullscreen').textContent='×';$('fullscreen').title='Plein écran indisponible';}};
$('help').onclick=()=>$('info').showModal();$('closeInfo').onclick=()=>$('info').close();$('info').onclick=e=>{if(e.target===$('info')){const r=$('info').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('info').close();}};
const canvas=$('battle'),ctx=canvas.getContext('2d');let W=1200,H=650,dpr=1;const sprites={};for(const side of ['green','red'])for(const kind of ['tank','soldier','jet']){let im=new Image();im.src=`assets/${side}-${kind}.png`;sprites[`${side}-${kind}`]=im;}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;}new ResizeObserver(resize).observe(canvas);resize();
const war=new War();let last=0;
function sprite(im,x,y,size,alpha=1,rotation=0){if(!im.complete||!im.naturalWidth)return;ctx.save();ctx.translate(x,y);ctx.rotate(rotation);ctx.globalAlpha=alpha;ctx.drawImage(im,-size/2,-size*im.naturalHeight/im.naturalWidth/2,size,size*im.naturalHeight/im.naturalWidth);ctx.restore();}
function frame(ts){requestAnimationFrame(frame);if(document.hidden){last=ts;return;}const dt=Math.min((ts-last)/1000||.016,.05);last=ts;war.step(dt,{...stats,live,reduced});ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);const scale=Math.max(.62,Math.min(1.25,W/1200));
 const imageFor=u=>sprites[(u.side===0?'green':'red')+'-'+u.kind];
 ctx.strokeStyle='#b8a0ff24';ctx.lineWidth=1;ctx.setLineDash([4,9]);ctx.beginPath();ctx.moveTo(war.front*W,.33*H);ctx.lineTo(war.front*W,.94*H);ctx.stroke();ctx.setLineDash([]);
 for(const w of war.wrecks){const fade=Math.min(1,(18-w.age)/4);ctx.save();ctx.filter='grayscale(1) brightness(.3)';sprite(imageFor(w),w.x*W,w.y*H,(w.kind==='tank'?74:25)*scale,fade*.85,w.kind==='soldier'?1.4:.12);ctx.restore();if(w.kind==='tank'&&w.age<8&&!reduced){const x=w.x*W,y=w.y*H;ctx.fillStyle='#ff8b3266';ctx.beginPath();ctx.ellipse(x,y-7,5*scale,10*scale*(1+Math.sin(war.time*14+w.phase)*.2),0,0,7);ctx.fill();ctx.fillStyle='#47484c55';ctx.beginPath();ctx.ellipse(x+Math.sin(war.time+w.phase)*8,y-22-w.age*3,12+w.age,16+w.age,0,0,7);ctx.fill();}}
 for(const u of [...war.units].sort((a,b)=>a.y-b.y)){const tank=u.kind==='tank',size=(tank?78:25)*scale,x=u.x*W,y=u.y*H,bob=!reduced&&u.move?Math.sin(war.time*(tank?14:19)+u.phase)*(tank?.5:2):0;
 ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(x,y+size*.18,size*.29,size*.08,0,0,7);ctx.fill();sprite(imageFor(u),x,y+bob,size,Math.min(1,u.age*3));
 if(u.flash>0){const mx=x+(u.side===0?1:-1)*size*.42;ctx.fillStyle='#ffe7aa';ctx.beginPath();ctx.ellipse(mx,y, tank?12:5,tank?4:2,0,0,7);ctx.fill();}
 if(u.age<1&&!reduced){ctx.strokeStyle=u.side===0?'#39e89a77':'#ff505d77';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y+size*.2,size*.4,size*.12,0,0,7);ctx.stroke();}
 }
 for(const j of war.jets){const x=j.x*W,y=j.y*H;ctx.strokeStyle=j.side===0?'#39e89a55':'#ff505d55';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x-(j.side===0?1:-1)*110*scale,y);ctx.lineTo(x,y);ctx.stroke();sprite(sprites[(j.side===0?'green':'red')+'-jet'],x,y,140*scale);}
 for(const s of war.shots){const q=s.age/s.duration,x=(s.x+(s.tx-s.x)*q)*W,y=(s.y+(s.ty-s.y)*q)*H-Math.sin(q*Math.PI)*22*s.p;ctx.strokeStyle=s.side===0?'#b4ffd1':'#ffc0a0';ctx.lineWidth=s.p>.5?2.3:1.2;ctx.beginPath();ctx.moveTo(x-(s.tx-s.x)*W*.07,y-(s.ty-s.y)*H*.07);ctx.lineTo(x,y);ctx.stroke();ctx.fillStyle='#fff3ca';ctx.fillRect(x-1.5,y-1.5,3,3);}
 for(const b of war.effects){const x=b.x*W,y=b.y*H,p=b.p*scale,t=b.age;if(t<.5){let radius=(8+t*65)*p;const g=ctx.createRadialGradient(x,y,0,x,y,Math.max(1,radius));g.addColorStop(0,`rgba(255,247,211,${Math.max(0,1-t*2)})`);g.addColorStop(.3,`rgba(255,150,36,${Math.max(0,.9-t*1.8)})`);g.addColorStop(1,'rgba(240,45,12,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,radius,0,7);ctx.fill();}if(!reduced&&p>.4){for(let i=0;i<9;i++){const a=i*.7+b.seed,d=t*55*p;ctx.fillStyle=`rgba(255,174,68,${Math.max(0,1-t)})`;ctx.fillRect(x+Math.cos(a)*d,y+Math.sin(a)*d*.6+t*t*12,3,2);}ctx.fillStyle=`rgba(77,75,80,${Math.max(0,.2-t*.07)})`;ctx.beginPath();ctx.ellipse(x+t*7,y-t*22,(8+t*15)*p,(6+t*18)*p,0,0,7);ctx.fill();}}
 if(war.impacts.length&&war.time-lastSound>.12){rumble(Math.min(1.5,Math.max(...war.impacts)));lastSound=war.time;}
}
let lastSound=0;
requestAnimationFrame(frame);connect();setInterval(update,1000);update();
window.addEventListener('pagehide',()=>{stopped=true;clearTimeout(retryTimer);socket?.close();});window.addEventListener('pageshow',e=>{if(e.persisted){stopped=false;connect();}});
